<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/auth-server.php';require_once dirname(__DIR__).'/php/payments-repository.php';require_once dirname(__DIR__).'/php/cash-flow-repository.php';require_once dirname(__DIR__).'/php/cash-change-schema.php';require_once dirname(__DIR__).'/php/company-repository.php';
function changeCheck(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function changeReject(callable $fn):void{try{$fn();}catch(InvalidArgumentException|PDOException){return;}throw new RuntimeException('Se aceptó un vuelto inválido.');}
$s=startAuthTestServer();$cookie=tempnam(sys_get_temp_dir(),'cash-change-');
try{
    $db=$s['db'];$setup=prepareFirstAdministrator($db);$prefix='Vuelto'.bin2hex(random_bytes(4));$password=bin2hex(random_bytes(12));$login=strtolower($prefix);$actor=createFirstAdministrator($db,['name'=>$prefix,'login'=>$login,'password'=>$password,'password_confirmation'=>$password],hash('sha256',$setup));
    echo "RUN configuración y cobro con vuelto\n";
    [, $html]=authTestRequest($s,'/login.php',$cookie);changeCheck(authTestRequest($s,'/login.php',$cookie,['csrf'=>authTestToken($html),'login'=>$login,'password'=>$password])[0]===303,'Falló login.');
    $configPath='/modules/contabilidad/configuracion.php?section=methods&new=1';[, $html]=authTestRequest($s,$configPath,$cookie);$csrf=authTestToken($html);changeCheck(str_contains($html,'name="allow_change"'),'No aparece Permitir vuelto.');
    changeCheck(authTestRequest($s,$configPath,$cookie,['csrf'=>$csrf,'action'=>'save_configuration','name'=>$prefix,'allow_change'=>'1'])[0]===303,'No se pudo crear el método.');
    $q=$db->prepare('SELECT * FROM accounting_payment_methods WHERE name=?');$q->execute([$prefix]);$method=$q->fetch();changeCheck((int)$method['allow_change']===1,'No se guardó el check.');
    $cash=(int)$method['id'];$manual=(int)$db->query("SELECT id FROM accounting_payment_methods WHERE system_key='manual'")->fetchColumn();$type=(int)$db->query("SELECT id FROM contact_types WHERE system_key='client'")->fetchColumn();
    $db->prepare('INSERT INTO contacts(name,type_id) VALUES(?,?)')->execute([$prefix,$type]);$contact=(int)$db->lastInsertId();
    $accounts=[];foreach(['cash','bank'] as $kind){$db->prepare('INSERT INTO accounting_payment_accounts(name,account_type,currency_code) VALUES(?,?,?)')->execute([$prefix.$kind,$kind,'USD']);$accounts[$kind]=(int)$db->lastInsertId();}
    $today=commerceToday();$input=['partner_type'=>'customer','direction'=>'inbound','contact_id'=>$contact,'amount'=>'999.00','received_amount'=>'20.00','change_amount'=>'2.00','account_id'=>$accounts['cash'],'method_id'=>$cash,'currency_code'=>'USD','payment_date'=>$today,'reference'=>$prefix];
    $key=bin2hex(random_bytes(32));$payment=saveAccountingPayment($db,$input,null,null,$key);changeCheck(saveAccountingPayment($db,$input,null,null,$key)===$payment,'Un reenvío duplicó el pago.');
    $p=loadAccountingPayment($db,$payment);changeCheck($p['amount']==='18.00'&&$p['received_amount']==='20.00'&&$p['change_amount']==='2.00'&&$p['available']==='18.00','Se confió en el neto enviado por el navegador.');
    $entries=$db->prepare('SELECT * FROM accounting_treasury_entries WHERE payment_id=? ORDER BY id');$entries->execute([$payment]);changeCheck(!$entries->fetchAll(),'Un borrador generó movimientos.');
    transitionAccountingPayment($db,$payment,1,'post_payment');transitionAccountingPayment($db,$payment,2,'settle_payment');treasuryPostPayment($db,['id'=>$payment]);
    $entries->execute([$payment]);$posted=$entries->fetchAll();changeCheck(count($posted)===2&&array_column($posted,'amount')===['20.00','-2.00']&&array_column($posted,'flow_amount')===['18.00','0.00'],'No se guardaron las dos partidas o se duplicaron.');
    $range=cashFlowRange([]);$summary=array_column(loadCashFlowSummary($db,$range,$accounts['cash'])['currencies'],null,'code')['USD'];
    changeCheck($summary['income']==='18.00'&&$summary['expense']==='0.00'&&$summary['balance_end']==='18.00'&&$summary['cash_received']==='20.00'&&$summary['cash_change']==='2.00','El vuelto infló ingresos o egresos.');
    $methods=loadCashFlowMethods($db,$range,$accounts['cash']);changeCheck($methods[0]['income']==='18.00'&&$methods[0]['expense']==='0.00','El desglose por método usa el bruto.');
    [, $html]=authTestRequest($s,'/modules/contabilidad/pagos.php?type=customer&id='.$payment,$cookie);changeCheck(str_contains($html,'data-cash-saved="1"')&&str_contains($html,'name="received_amount"')&&str_contains($html,'value="20.00"'),'La ficha no conserva el efectivo recibido.');
    [, $html]=authTestRequest($s,'/modules/contabilidad/ingresos-egresos.php?account_id='.$accounts['cash'],$cookie);changeCheck(str_contains($html,'Vuelto entregado')&&str_contains($html,'-2.00 USD'),'El historial no identifica el vuelto.');
    echo "RUN validaciones y reversión\n";
    foreach([['change_amount'=>'-1'],['change_amount'=>'20'],['change_amount'=>'21'],['change_amount'=>'1.001'],['received_amount'=>'bad'],['method_id'=>$manual],['account_id'=>$accounts['bank']],['direction'=>'outbound']] as $override)changeReject(fn()=>saveAccountingPayment($db,array_replace($input,$override),null,null,bin2hex(random_bytes(32))));
    $zero=saveAccountingPayment($db,array_replace($input,['change_amount'=>'0']),null,null,bin2hex(random_bytes(32)));changeCheck(loadAccountingPayment($db,$zero)['available']==='20.00','El excedente sin vuelto dejó de estar disponible.');
    transitionAccountingPayment($db,$zero,1,'post_payment');transitionAccountingPayment($db,$zero,2,'settle_payment');$entries->execute([$zero]);$zeroEntries=$entries->fetchAll();changeCheck(count($zeroEntries)===1&&$zeroEntries[0]['amount']==='20.00','Un vuelto cero creó una salida innecesaria.');reverseAccountingPayment($db,$zero,3,['reason'=>$prefix,'movement_date'=>$today]);
    $edit=saveAccountingPayment($db,['partner_type'=>'customer','direction'=>'inbound','contact_id'=>$contact,'amount'=>'18','change_amount'=>'2','account_id'=>$accounts['cash'],'method_id'=>$cash,'currency_code'=>'USD','payment_date'=>$today],null,null,bin2hex(random_bytes(32)));changeCheck(loadAccountingPayment($db,$edit)['received_amount']==='20.00','El importe neto de importación se interpretó como bruto.');
    $db->prepare("INSERT INTO accounting_invoices(invoice_type,contact_id,invoice_address,invoice_date,base_amount,total_amount,status,currency_code) VALUES('customer',?,'',?,18,18,'posted','USD')")->execute([$contact,$today]);$invoice=(int)$db->lastInsertId();
    paymentFromInvoice($db,$invoice,1,'register_payment',array_replace($input,['change_amount'=>'0']));$q=$db->prepare('SELECT payment_id,amount FROM accounting_invoice_payments WHERE invoice_id=?');$q->execute([$invoice]);$allocation=$q->fetch();changeCheck($allocation['amount']==='18.00'&&loadAccountingPayment($db,(int)$allocation['payment_id'])['available']==='2.00','Dejar vuelto cero no conserva el saldo a favor después de pagar la factura.');
    $atomic=saveAccountingPayment($db,$input,null,null,bin2hex(random_bytes(32)));transitionAccountingPayment($db,$atomic,1,'post_payment');
    $db->exec("CREATE TRIGGER test_reject_cash_change BEFORE INSERT ON accounting_treasury_entries FOR EACH ROW BEGIN IF NEW.cash_role='cash_change' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Fallo de prueba al entregar vuelto'; END IF; END");
    try{changeReject(fn()=>transitionAccountingPayment($db,$atomic,2,'settle_payment'));}finally{$db->exec('DROP TRIGGER test_reject_cash_change');}
    $entries->execute([$atomic]);changeCheck(!$entries->fetchAll()&&loadAccountingPayment($db,$atomic)['status']==='pending'&&treasuryBalance($db,$accounts['cash'],'USD',$today)==='18.00','Un fallo al entregar vuelto dejó una entrada parcial.');
    $reverse=reverseAccountingPayment($db,$payment,3,['reason'=>$prefix,'movement_date'=>$today]);$q=$db->prepare('SELECT amount,flow_amount FROM accounting_treasury_entries WHERE document_id=? ORDER BY id');$q->execute([$reverse]);$rows=$q->fetchAll();changeCheck(array_column($rows,'amount')===['-20.00','2.00']&&array_column($rows,'flow_amount')===['-18.00','0.00'],'La reversión no compensa ambas partidas.');
    changeCheck(treasuryBalance($db,$accounts['cash'],'USD',$today)==='0.00','La reversión no restauró el saldo.');changeReject(fn()=>reverseAccountingPayment($db,$payment,4,['reason'=>$prefix,'movement_date'=>$today]));
    $before=$db->query('SELECT COUNT(*) FROM accounting_treasury_entries')->fetchColumn();installCashChange($db);installCashChange($db);changeCheck($db->query('SELECT COUNT(*) FROM accounting_treasury_entries')->fetchColumn()===$before,'Reinstalar duplicó los movimientos.');
    $db->prepare('UPDATE accounting_payment_methods SET allow_change=0 WHERE id=?')->execute([$cash]);installCashChange($db);$q=$db->prepare('SELECT allow_change FROM accounting_payment_methods WHERE id=?');$q->execute([$cash]);changeCheck((int)$q->fetchColumn()===0&&loadAccountingPayment($db,$payment)['change_enabled']==1,'Reinstalar o cambiar el método alteró decisiones o pagos históricos.');
    echo "PASS: check por método, recibido/vuelto/neto, confirmación atómica, reenvío, saldo disponible, validaciones, reportes, historial, reversión e instalación repetible.\n";
}catch(Throwable $e){fwrite(STDERR,$e->getMessage().PHP_EOL);throw $e;}
finally{if(is_file($cookie))unlink($cookie);stopAuthTestServer($s);}
